messages.content:
Prepare six useful optional communication cards for the fictional person and activity below. Follow the supplied communication style and maximum words per card. Return only a JSON object with the key "cards" containing exactly six nonempty strings. Do not include commentary.


FICTIONAL CASE:
{"profile": {"name": "Sam", "age": 10, "communication_style": "short phrases"}, "activity": "Prepare a snack using sliced apples, bananas, plain yogurt, bowls and spoons.", "facts": ["Sam has said they like apples.", "Sam has said they dislike mushy bananas.", "Nothing is known about allergies or medical dietary restrictions.", "Sam can ask for a different snack."], "shared_context": "This is a fictional authoring exercise. The person’s full existing communication system stays available. These are optional supplemental phrase cards, not claims about current intent.", "word_limit": 8}

message.content:
{
  "cards": [
    "Sam prefers short phrases. Use 'I like apples' instead of 'I love apples.'",
    "Sam dislikes mushy bananas. Choose soft, ripe fruit like strawberries.",
    "Nothing is known about Sam's allergies or medical restrictions.",
    "If Sam asks, ask politely: 'Do you have any restrictions?'",
    "Use 'Please' when requesting snacks.",
    "Keep sentences under 8 words to maintain the short phrase style."
  ]
}
